import AbstractStatefulView from '../framework/view/abstract-stateful-view.js';
import { formatDateTime } from '../utils.js';
import { DATE_FORMAT } from '../const.js';
import flatpickr from 'flatpickr';
import 'flatpickr/dist/flatpickr.min.css';

const POINTS_TYPE = [
  'Taxi', 'Bus', 'Train', 'Ship', 'Drive',
  'Flight', 'Check-in', 'Sightseeing', 'Restaurant'
];

function getCanonicalType(formValue) {
  return POINTS_TYPE.find((type) => type.toLowerCase().replace('-', '') === formValue) || formValue;
}

function createTypeSelector(currentType) {
  return POINTS_TYPE.map((type) => {
    const lowerType = type.toLowerCase().replace('-', '');
    const isChecked = type === currentType;
    return `
      <div class="event__type-item">
        <input
          id="event-type-${lowerType}-1"
          class="event__type-input visually-hidden"
          type="radio"
          name="event-type"
          value="${lowerType}"
          ${isChecked ? 'checked' : ''}
        >
        <label class="event__type-label event__type-label--${lowerType}" for="event-type-${lowerType}-1">
          ${type}
        </label>
      </div>
    `;
  }).join('');
}

function createDestinationsOptions(destinations, selectedId) {
  return destinations.map((d) =>
    `<option value="${d.id}" ${d.id === selectedId ? 'selected' : ''}>${d.name}</option>`
  ).join('');
}

function createOffersList(offersByType, pointType, selectedOfferIds) {
  const offers = offersByType[pointType] || [];
  return offers.map((offer) => {
    const isChecked = selectedOfferIds.includes(offer.id);
    return `
      <div class="event__offer-selector">
        <input
          class="event__offer-checkbox visually-hidden"
          id="offer-${offer.id}"
          type="checkbox"
          name="offer-${offer.id}"
          value="${offer.id}"
          ${isChecked ? 'checked' : ''}
        >
        <label class="event__offer-label" for="offer-${offer.id}">
          <span class="event__offer-title">${offer.title}</span>
          &plus;&euro;&nbsp;
          <span class="event__offer-price">${offer.price}</span>
        </label>
      </div>
    `;
  }).join('');
}

function createEditFormTemplate(state, availableOffers, destinations) {
  const {
    type: currentType,
    destinationId,
    startTime = new Date(),
    endTime = new Date(),
    basePrice,
    offers: selectedOffers } = state;

  const typeSelector = createTypeSelector(currentType);

  const selectedDest = destinations.find((d) => d.id === destinationId) || destinations[0] || null;

  const selectedDestId = selectedDest ? selectedDest.id : '';

  const description = selectedDest ? selectedDest.description : '';
  const selectedDestName = selectedDest ? selectedDest.name : '';
  const destinationsOptions = createDestinationsOptions(destinations, selectedDestId);

  const startTimeFormatted = formatDateTime(startTime);
  const endTimeFormatted = formatDateTime(endTime);

  const offersList = createOffersList(availableOffers, currentType, selectedOffers || []);

  return `
    <li class="trip-events__item">
      <form class="event event--edit" action="#" method="post">
        <header class="event__header">
          <div class="event__type-wrapper">
            <label class="event__type event__type-btn" for="event-type-toggle-1">
              <span class="visually-hidden">Choose event type</span>
              <img
                class="event__type-icon"
                width="17"
                height="17"
                src="img/icons/${currentType.toLowerCase()}.png"
                alt="Event type icon"
              >
            </label>
            <input class="event__type-toggle visually-hidden" id="event-type-toggle-1" type="checkbox">
            <div class="event__type-list">
              <fieldset class="event__type-group">
                <legend class="visually-hidden">Event type</legend>
                ${typeSelector}
              </fieldset>
            </div>
          </div>
          <div class="event__field-group event__field-group--destination">
            <label class="event__label event__type-output" for="event-destination-1">
              ${currentType}
            </label>
            <input class="event__input  event__input--destination" id="event-destination-1" type="text" name="event-destination" value="${selectedDestName}" list="destination-list-1" />
            <datalist id="destination-list-1">
              ${destinationsOptions}
            </datalist>
          </div>
          <div class="event__field-group event__field-group--time">
            <label class="visually-hidden" for="event-start-time-1">From</label>
            <input
              class="event__input event__input--time"
              id="event-start-time-1"
              type="text"
              name="event-start-time"
              value="${startTimeFormatted}"
            >
            &mdash;
            <label class="visually-hidden" for="event-end-time-1">To</label>
            <input
              class="event__input event__input--time"
              id="event-end-time-1"
              type="text"
              name="event-end-time"
              value="${endTimeFormatted}"
            >
          </div>
          <div class="event__field-group event__field-group--price">
            <label class="event__label" for="event-price-1">
              <span class="visually-hidden">Price</span>
              &euro;
            </label>
            <input
              class="event__input event__input--price"
              id="event-price-1"
              type="text"
              name="event-price"
              value="${basePrice}"
            >
          </div>
          <button class="event__save-btn btn btn--blue" type="submit">Save</button>
          <button class="event__reset-btn" type="reset">${state.id ? 'Delete' : 'Cancel'}</button>
          <button class="event__rollup-btn" type="button">
            <span class="visually-hidden">Open event</span>
          </button>
        </header>
        <section class="event__details">
          <section class="event__section event__section--offers">
            <h3 class="event__section-title event__section-title--offers">Offers</h3>
            <div class="event__available-offers">
              ${offersList}
            </div>
          </section>
          <section class="event__section event__section--destination">
            <h3 class="event__section-title event__section-title--destination">Destination</h3>
            <p class="event__destination-description">${description}</p>
            ${(selectedDest?.pictures || []).map((pictureUrl) => `
              <div class="event__photo-wrapper">
                <img class="event__photo" src="${pictureUrl}" alt="Destination photo">
              </div>
            `).join('')}
          </section>
        </section>
      </form>
    </li>
  `;
}

export default class EditFormView extends AbstractStatefulView {
  #handleFormSubmit = null;
  #handleFormClose = null;
  #datepickerStart = null;
  #datepickerEnd = null;
  #destinations = null;
  #offers = null;

  constructor({ point, destinations, offers, onFormSubmit, onFormClose }) {
    super();
    this._setState(EditFormView.parseFormDataToState(point));
    this.#handleFormSubmit = onFormSubmit;
    this.#handleFormClose = onFormClose;
    this.#destinations = destinations;
    this.#offers = offers;

    this._restoreHandlers();
  }

  get template() {
    return createEditFormTemplate(this._state, this.#offers, this.#destinations);
  }

  _restoreHandlers() {
    this.element.querySelector('form').addEventListener('submit', this.#formSubmitHandler);
    this.element.querySelector('.event__rollup-btn').addEventListener('click', this.#formCloseHandler);
    this.element.querySelector('.event__type-group').addEventListener('change', this.#typeChangeHandler);
    this.element.querySelector('.event__input--destination').addEventListener('change', this.#destinationChangeHandler);
    this.element.querySelector('.event__available-offers').addEventListener('change', this.#offerChangeHandler);
    this.element.querySelector('.event__input--price').addEventListener('input', this.#priceInputHandler);
    this.#setDatepickerStart();
    this.#setDatepickerEnd();
  }

  #formSubmitHandler = (evt) => {
    evt.preventDefault();
    this.#handleFormSubmit(this._state);
  };

  #formCloseHandler = () => {
    this.#handleFormClose();
  };

  #typeChangeHandler = (evt) => {
    evt.preventDefault();
    const canonicalType = getCanonicalType(evt.target.value);
    this.updateElement({
      type: canonicalType,
      offers: []
    });
  };

  #destinationChangeHandler = (evt) => {
    const destinationName = evt.target.value;
    const destination = this.#destinations.find((d) => d.name === destinationName);

    this.updateElement({
      destinationId: destination.id,
      cityName: destination.name
    });
  };

  #offerChangeHandler = (evt) => {
    evt.preventDefault();
    const offerId = evt.target.value;
    const currentOffers = this._state.offers || [];
    const newOffers = evt.target.checked
      ? [...currentOffers, offerId]
      : currentOffers.filter((id) => id !== offerId);

    this.updateElement({
      offers: newOffers
    });
  };

  #priceInputHandler = (evt) => {
    this.updateElement({
      basePrice: evt.target.value
    });
  };

  static parseFormDataToState(point) {
    return { ...point };
  }

  removeElement() {
    super.removeElement();

    if (this.#datepickerStart) {
      this.#datepickerStart.destroy();
      this.#datepickerStart = null;
    }

    if (this.#datepickerEnd) {
      this.#datepickerEnd.destroy();
      this.#datepickerEnd = null;
    }
  }

  #dateStartChangeHandler = ([userDate]) => {
    this.updateElement({
      startTime: userDate,
    });
  };

  #dateEndChangeHandler = ([userDate]) => {
    this.updateElement({
      endTime: userDate,
    });
  };

  #setDatepickerStart() {
    this.#datepickerStart = flatpickr(
      this.element.querySelector('#event-start-time-1'),
      {
        dateFormat: DATE_FORMAT,
        defaultDate: this._state.startTime,
        enableTime: true,
        'time_24hr': true,
        minDate: 'today',
        maxDate: this._state.endTime,
        onChange: this.#dateStartChangeHandler,
      },
    );
  }

  #setDatepickerEnd() {
    this.#datepickerEnd = flatpickr(
      this.element.querySelector('#event-end-time-1'),
      {
        dateFormat: DATE_FORMAT,
        defaultDate: this._state.endTime,
        enableTime: true,
        'time_24hr': true,
        minDate: this._state.startTime,
        onChange: this.#dateEndChangeHandler,
      },
    );
  }

  requestDate() {
    this.#setDatepickerStart();
    this.#setDatepickerEnd();
  }
}
